def word_count(text):
    words = [word.strip('.,!?').lower() for word in text.split()]
    counts = {}
    for w in words:
        if w:  # Skip empty strings after stripping
            counts[w] = counts.get(w, 0) + 1
    return counts

def word_count(text):
    counts = {}
    for w in text.split():
        # Remove leading/trailing punctuation and convert to lowercase
        w = ''.join(c for c in w if c.isalnum()).lower()
        counts[w] = counts.get(w, 0) + 1
    return counts

def index_of(xs, x):
    lo, hi = 0, len(xs)
    while lo < hi:
        mid = (lo + hi) // 2
        if xs[mid] < x:
            lo = mid + 1
        else:
            hi = mid
    return lo if lo < len(xs) and xs[lo] == x else -1

