def caesar(s, k):
    result = []
    for char in s:
        if char.isalpha():
            # Find the position of the character in the alphabet
            base = ord('A') if char.isupper() else ord('a')
            # Calculate the new position
            new_pos = (ord(char) - base + k) % 26 + base
            # Convert back to a character
            result.append(chr(new_pos))
        else:
            result.append(char)
    return ''.join(result)

def caesar(s, k):
    result = []
    for char in s:
        if 'A' <= char <= 'Z':
            shifted = (ord(char) - ord('A') + k) % 26
            result.append(chr(ord('A') + shifted))
        elif 'a' <= char <= 'z':
            shifted = (ord(char) - ord('a') + k) % 26
            result.append(chr(ord('a') + shifted))
        else:
            result.append(char)
    return ''.join(result)
